const message = (text?: string, id?: string) => text && <p id={id} role="alert" aria-live="assertive" aria-atomic="true" className="mt-1.5 text-xs text-destructive">{text}</p>;

function FormSuccess({ title, copy }: { title: string; copy: string }) {
  return <div role="status" aria-live="polite" className="surface rounded-xl p-9 text-center"><CheckCircle2 className="mx-auto size-12 text-success" /><h3 className="mt-4 font-heading text-2xl font-semibold">{title}</h3><p className="mt-3 text-sm leading-6 text-muted-foreground">{copy}</p></div>;
}

const applyFieldOrder = ["name", "email", "phone", "linkedIn", "portfolio", "coverLetter", "skills", "resume"] as const;
type ApplyField = typeof applyFieldOrder[number];

const applyFieldIds: Record<ApplyField, string> = {
  name: "apply-name",
  email: "apply-email",
  phone: "apply-phone",
  linkedIn: "apply-linkedin",
  portfolio: "apply-portfolio",
  coverLetter: "apply-cover",
  skills: "apply-skills",
  resume: "apply-resume",
};

function formatFileSize(bytes: number) {
  if (bytes >= 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(2)} MB`;
  return `${(bytes / 1024).toFixed(1)} KB`;
}

export function PartnerInquiryForm() {
  const [done, setDone] = useState(false);
  const [serverError, setServerError] = useState("");
  const { register, handleSubmit, control, formState: { errors, isSubmitting } } = useForm<PartnerInput>({
    resolver: zodResolver(partnerSchema),
    defaultValues: { name: "", email: "", phone: "", company: "", website: "", partnershipType: "", message: "" },
  });
  const onSubmit = async (values: PartnerInput) => {
    setServerError("");
    try {
      openMailto({
        to: SUPPORT_EMAIL,
        subject: `Partnership inquiry — ${values.partnershipType || "general"}`,
        body: [
          `Name: ${values.name}`,
          `Email: ${values.email}`,
          `Phone: ${values.phone || "—"}`,
          `Organization: ${values.company}`,
          `Website: ${values.website || "—"}`,
          `Partnership model: ${values.partnershipType}`,
          "",
          values.message,
          "",
          `— Sent from the CITIS InfoTech partner form`,
        ].join("\n"),
      });
      setDone(true);
    }
    catch (error) { setServerError(error instanceof Error ? error.message : "Your inquiry could not be sent. Please try again."); }
  };
  if (done) return <FormSuccess title="Partnership inquiry draft ready" copy="Your email app should open a message to support@citis.in. Send it to complete your inquiry." />;
  return (
    <form onSubmit={handleSubmit(onSubmit)} className="surface space-y-5 rounded-xl p-6 sm:p-8" noValidate>
      <div className="grid gap-5 sm:grid-cols-2">
        <div><Label htmlFor="partner-name">Full name *</Label><Input id="partner-name" className="mt-2" autoComplete="name" aria-invalid={!!errors.name} aria-describedby={errors.name ? "partner-name-error" : undefined} {...register("name")} />{message(errors.name?.message, "partner-name-error")}</div>
        <div><Label htmlFor="partner-email">Work email *</Label><Input id="partner-email" className="mt-2" type="email" autoComplete="email" aria-invalid={!!errors.email} aria-describedby={errors.email ? "partner-email-error" : undefined} {...register("email")} />{message(errors.email?.message, "partner-email-error")}</div>
        <div><Label htmlFor="partner-phone">Phone</Label><Input id="partner-phone" className="mt-2" type="tel" aria-invalid={!!errors.phone} aria-describedby={errors.phone ? "partner-phone-error" : undefined} {...register("phone")} />{message(errors.phone?.message, "partner-phone-error")}</div>
        <div><Label htmlFor="partner-company">Organization *</Label><Input id="partner-company" className="mt-2" autoComplete="organization" aria-invalid={!!errors.company} aria-describedby={errors.company ? "partner-company-error" : undefined} {...register("company")} />{message(errors.company?.message, "partner-company-error")}</div>
        <div><Label htmlFor="partner-website">Website</Label><Input id="partner-website" className="mt-2" type="url" placeholder="https://" aria-invalid={!!errors.website} aria-describedby={errors.website ? "partner-website-error" : undefined} {...register("website")} />{message(errors.website?.message, "partner-website-error")}</div>
        <div><Label htmlFor="partner-partnership">Partnership model *</Label><Controller name="partnershipType" control={control} render={({ field }) => <Select value={field.value} onValueChange={field.onChange}><SelectTrigger id="partner-partnership" className="mt-2" aria-invalid={!!errors.partnershipType} aria-describedby={errors.partnershipType ? "partner-partnership-error" : undefined}><SelectValue placeholder="Select a model" /></SelectTrigger><SelectContent><SelectItem value="academic">Academic collaboration</SelectItem><SelectItem value="industry">Industry alliance</SelectItem><SelectItem value="delivery">Delivery partner</SelectItem><SelectItem value="technology">Technology partner</SelectItem></SelectContent></Select>} />{message(errors.partnershipType?.message, "partner-partnership-error")}</div>
      </div>
      <div><Label htmlFor="partner-message">What would you like to achieve? *</Label><Textarea id="partner-message" className="mt-2 min-h-32" placeholder="Share your institution, audience, priorities, and preferred timeline." aria-invalid={!!errors.message} aria-describedby={errors.message ? "partner-message-error" : undefined} {...register("message")} />{message(errors.message?.message, "partner-message-error")}</div>
      {serverError && <p role="alert" aria-live="assertive" className="rounded-lg bg-destructive/10 p-3 text-sm text-destructive">{serverError}</p>}
      <Button type="submit" variant="accent" size="lg" disabled={isSubmitting}>{isSubmitting ? <><LoaderCircle className="animate-spin" />Sending…</> : <>Send inquiry<Send /></>}</Button>
    </form>
  );
}

export function JobApplicationForm({ jobId, jobTitle }: { jobId: string; jobTitle: string }) {
  const [done, setDone] = useState(false);
  const [serverError, setServerError] = useState("");
  const [resumeFile, setResumeFile] = useState<File | null>(null);
  const focusValidationId = useRef(0);
  const { register, handleSubmit, reset, resetField, setValue, trigger, getFieldState, formState: { errors, isSubmitting } } = useForm<ApplyJobInput>({
    resolver: zodResolver(applyJobSchema),
    defaultValues: { name: "", email: "", phone: "", jobId, linkedIn: "", portfolio: "", coverLetter: "", skills: "" },
  });

  useEffect(() => {
    if (!done) return;

    const timeout = window.setTimeout(() => {
      setDone(false);
      setResumeFile(null);
      reset();
    }, 5000);

    return () => window.clearTimeout(timeout);
  }, [done, reset]);

  const handleApplyFieldFocus = async (field: ApplyField) => {
    const fieldIndex = applyFieldOrder.indexOf(field);
    if (fieldIndex <= 0) return;

    const validationId = ++focusValidationId.current;
    const previousFields = applyFieldOrder.slice(0, fieldIndex);
    const previousFieldsValid = await trigger(previousFields, { shouldFocus: false });
    if (validationId !== focusValidationId.current || previousFieldsValid) return;

    const firstInvalidField = previousFields.find((previousField) => getFieldState(previousField).invalid) || previousFields[previousFields.length - 1];
    document.getElementById(applyFieldIds[firstInvalidField])?.focus();
  };

  const onSubmit = async (values: ApplyJobInput) => {
    setServerError("");
    try {
      openMailto({
        to: CAREERS_EMAIL,
        subject: `Job application — ${jobTitle}`,
        body: [
          `Role: ${jobTitle}`,
          `Name: ${values.name}`,
          `Email: ${values.email}`,
          `Phone: ${values.phone}`,
          `LinkedIn: ${values.linkedIn || "—"}`,
          `Portfolio: ${values.portfolio || "—"}`,
          `Skills: ${values.skills || "—"}`,
          "",
          values.coverLetter || "",
          "",
          "Please attach your résumé to this email before sending.",
          "",
           `Résumé file: ${values.resume?.name || "—"}`,
           "",
           `— Sent from the CITIS InfoTech careers form`,
        ].join("\n"),
      });
      setDone(true);
    } catch (error) {
      setServerError(error instanceof Error ? error.message : "We could not submit your application. Please try again.");
    }
  };
   if (done) return <FormSuccess title="Application ready to send" copy={`Your email app should open a message to careers@citis.in for ${jobTitle}. Attach your résumé, then send the email to complete your application.`} />;
  return (
    <form onSubmit={handleSubmit(onSubmit)} className="surface space-y-5 rounded-xl p-6 sm:p-8" noValidate>
      <input type="hidden" {...register("jobId")} />
      <div className="grid gap-5 sm:grid-cols-2">
        <div><Label htmlFor="apply-name">Full name *</Label><Input id="apply-name" className="mt-2" required aria-invalid={!!errors.name} aria-describedby={errors.name ? "apply-name-error" : undefined} {...register("name")} onFocus={() => { void handleApplyFieldFocus("name"); }} />{message(errors.name?.message, "apply-name-error")}</div>
        <div><Label htmlFor="apply-email">Email *</Label><Input id="apply-email" className="mt-2" type="email" required aria-invalid={!!errors.email} aria-describedby={errors.email ? "apply-email-error" : undefined} {...register("email")} onFocus={() => { void handleApplyFieldFocus("email"); }} />{message(errors.email?.message, "apply-email-error")}</div>
        <div><Label htmlFor="apply-phone">Phone *</Label><Input id="apply-phone" className="mt-2" type="tel" required aria-invalid={!!errors.phone} aria-describedby={errors.phone ? "apply-phone-error" : undefined} {...register("phone")} onFocus={() => { void handleApplyFieldFocus("phone"); }} />{message(errors.phone?.message, "apply-phone-error")}</div>
        <div><Label htmlFor="apply-linkedin">LinkedIn</Label><Input id="apply-linkedin" className="mt-2" type="url" placeholder="https://linkedin.com/in/…" aria-invalid={!!errors.linkedIn} aria-describedby={errors.linkedIn ? "apply-linkedin-error" : undefined} {...register("linkedIn")} onFocus={() => { void handleApplyFieldFocus("linkedIn"); }} />{message(errors.linkedIn?.message, "apply-linkedin-error")}</div>
      </div>
      <div><Label htmlFor="apply-portfolio">Portfolio</Label><Input id="apply-portfolio" className="mt-2" type="url" placeholder="https://" aria-invalid={!!errors.portfolio} aria-describedby={errors.portfolio ? "apply-portfolio-error" : undefined} {...register("portfolio")} onFocus={() => { void handleApplyFieldFocus("portfolio"); }} />{message(errors.portfolio?.message, "apply-portfolio-error")}</div>
      <div><Label htmlFor="apply-cover">Why CITIS InfoTech? *</Label><Textarea id="apply-cover" className="mt-2 min-h-28" required aria-invalid={!!errors.coverLetter} aria-describedby={errors.coverLetter ? "apply-cover-error" : undefined} {...register("coverLetter")} onFocus={() => { void handleApplyFieldFocus("coverLetter"); }} />{message(errors.coverLetter?.message, "apply-cover-error")}</div>
      <div><Label htmlFor="apply-skills">Skills *</Label><Input id="apply-skills" className="mt-2" required aria-invalid={!!errors.skills} aria-describedby={errors.skills ? "apply-skills-error" : undefined} placeholder="React, Node.js, Instructional design…" {...register("skills")} onFocus={() => { void handleApplyFieldFocus("skills"); }} /><p className="mt-1 text-xs text-muted-foreground">Comma-separated skills</p>{message(errors.skills?.message, "apply-skills-error")}</div>
       <div>
         <Label htmlFor="apply-resume">Résumé *</Label>
         {resumeFile ? (
           <div className="mt-2 flex items-center justify-between gap-3 rounded-lg border border-success/30 bg-success/5 p-4 text-sm">
             <label htmlFor="apply-resume" className="flex min-w-0 cursor-pointer items-center gap-3">
               <CheckCircle2 className="size-5 shrink-0 text-success" />
               <span className="min-w-0">
                 <span className="block font-medium text-success">Uploaded</span>
                 <span className="block truncate text-muted-foreground">{resumeFile.name} · {formatFileSize(resumeFile.size)}</span>
               </span>
             </label>
             <button type="button" className="shrink-0 text-xs font-medium text-muted-foreground underline-offset-4 hover:text-foreground hover:underline" onClick={() => { setResumeFile(null); resetField("resume"); const input = document.getElementById("apply-resume") as HTMLInputElement | null; if (input) input.value = ""; }}>Remove</button>
           </div>
         ) : (
           <label htmlFor="apply-resume" className="mt-2 flex cursor-pointer items-center gap-3 rounded-lg border border-dashed border-input bg-background p-4 text-sm hover:border-primary/50"><Upload className="size-5 text-primary" />Choose a file</label>
         )}
          <Input id="apply-resume" className="sr-only" required type="file" accept=".pdf,.doc,.docx" aria-invalid={!!errors.resume} aria-describedby={errors.resume ? "apply-resume-error" : undefined} onFocus={() => { void handleApplyFieldFocus("resume"); }} onChange={(event) => { const file = event.target.files?.[0]; if (file) { setResumeFile(file); setValue("resume", file, { shouldValidate: true }); } else { setResumeFile(null); resetField("resume"); } }} />
          {message(errors.resume?.message, "apply-resume-error")}
       </div>
      {serverError && <p role="alert" aria-live="assertive" className="rounded-lg bg-destructive/10 p-3 text-sm text-destructive">{serverError}</p>}
      <Button type="submit" variant="accent" size="lg" disabled={isSubmitting}>{isSubmitting ? <><LoaderCircle className="animate-spin" />Submitting…</> : <>Submit application<Send /></>}</Button>
    </form>
  );
}

function redirectToPortal(portal: LmsPortal, portalOrigin: string, provider?: LmsCourseProvider) {
  const hostname = window.location.hostname;
  const destinationOrigin =
    portal === "admin" && hostname === "admin.citisinfotech.in"
      ? window.location.origin
      : portal === "admin" && hostname === "lms.citisinfotech.in"
        ? "https://admin.citisinfotech.in"
      : portalOrigin;
  const destination = new URL("/", destinationOrigin);
  if (provider) destination.searchParams.set("provider", provider);
  window.location.assign(destination.toString());
}

export function LoginForm({ portal = "learner", provider, portalOrigin }: { portal?: LmsPortal; provider?: LmsCourseProvider; portalOrigin: string }) {
  const credentialPrefix = `citis-${portal}-login`;
  const emailInputId = `${credentialPrefix}-email`;
  const passwordInputId = `${credentialPrefix}-password`;
  const [show, setShow] = useState(false);
  const [serverError, setServerError] = useState("");
  const [mfaChallenge, setMfaChallenge] = useState<{ challengeToken: string; channel: "EMAIL" | "SMS"; expiresInSeconds: number } | null>(null);
  const [mfaCode, setMfaCode] = useState("");
  const [mfaSubmitting, setMfaSubmitting] = useState(false);
  const loginInFlightRef = useRef(false);
  const submissionIdRef = useRef(0);
  const { handleSubmit, control, reset, formState: { errors, isSubmitting } } = useForm<LoginInput>({ resolver: zodResolver(loginSchema), defaultValues: { email: "", password: "", remember: false } });
  useEffect(() => {
    reset({ email: "", password: "", remember: false });
    setShow(false);
    setServerError("");
  }, [portal, reset]);
  const onSubmit = async (values: LoginInput) => {
    if (loginInFlightRef.current) return;
    loginInFlightRef.current = true;
    const submissionId = ++submissionIdRef.current;
    let stage = "login";
    setServerError("");
    try {
      const login = await authService.login(values.email, values.password);
      if (login.data.mfaRequired && login.data.challengeToken && login.data.channel) {
        setMfaChallenge({
          challengeToken: login.data.challengeToken,
          channel: login.data.channel,
          expiresInSeconds: login.data.expiresInSeconds || 600,
        });
        return;
      }
      stage = "auth/me";
      try {
        const response = await authService.me();
        stage = "role-check";
        if (!canAccessLmsPortal(response.data, portal)) {
          const availablePortal = firstAvailableLmsPortal(response.data);
          const availableCopy = availablePortal ? ` This account belongs in the ${LMS_PORTALS[availablePortal].label}.` : "";
          throw new Error(`This account does not have access to the ${LMS_PORTALS[portal].label}.${availableCopy}`);
        }
        stage = "redirect";
        redirectToPortal(portal, portalOrigin, provider);
      } catch (error) {
        // Do not leave a valid session behind when role validation or the
        // follow-up session check fails.
        await authService.logout().catch(() => undefined);
        throw error;
      }
    } catch (error) {
      if (submissionId === submissionIdRef.current) {
        setServerError(loginErrorMessage(error, stage));
      }
    } finally {
      if (submissionId === submissionIdRef.current) {
        loginInFlightRef.current = false;
      }
    }
  };
  const verifyMfa = async (event: React.FormEvent) => {
    event.preventDefault();
    if (!mfaChallenge || mfaSubmitting || !/^\d{6}$/.test(mfaCode)) return;
    setMfaSubmitting(true);
    setServerError("");
    try {
      await authService.verifyMfaLogin(mfaChallenge.challengeToken, mfaCode);
      const response = await authService.me();
      if (!canAccessLmsPortal(response.data, portal)) {
        const availablePortal = firstAvailableLmsPortal(response.data);
        const availableCopy = availablePortal ? ` This account belongs in the ${LMS_PORTALS[availablePortal].label}.` : "";
        throw new Error(`This account does not have access to the ${LMS_PORTALS[portal].label}.${availableCopy}`);
      }
      redirectToPortal(portal, portalOrigin, provider);
    } catch (error) {
      await authService.logout().catch(() => undefined);
      setServerError(error instanceof Error ? error.message : "Verification failed. Please try again.");
    } finally {
      setMfaSubmitting(false);
    }
  };
  if (mfaChallenge) {
    return (
      <form onSubmit={verifyMfa} className="auth-form space-y-5" noValidate>
        <div>
          <Label htmlFor="login-mfa-code">Verification code</Label>
          <p className="mt-1.5 text-sm text-muted-foreground">
            Enter the 6-digit code sent by {mfaChallenge.channel === "EMAIL" ? "email" : "SMS"}. It expires in {Math.ceil(mfaChallenge.expiresInSeconds / 60)} minutes.
          </p>
          <div className="auth-field-wrap">
            <KeyRound className="auth-field-icon" aria-hidden="true" />
          <Input
            id="login-mfa-code"
            className="auth-input mt-2 min-h-12 rounded-xl bg-background/70 px-4 pl-11 tracking-[0.35em]"
            inputMode="numeric"
            autoComplete="one-time-code"
            maxLength={6}
            value={mfaCode}
            aria-invalid={Boolean(serverError)}
            aria-describedby={serverError ? "login-mfa-error" : undefined}
            onChange={(event) => { setMfaCode(event.target.value.replace(/\D/g, "").slice(0, 6)); setServerError(""); }}
            autoFocus
          />
          </div>
        </div>
        {serverError && <p id="login-mfa-error" role="alert" aria-live="assertive" className="rounded-xl border border-destructive/20 bg-destructive/10 p-3 text-sm text-destructive">{serverError}</p>}
        <Button className="auth-submit-button h-12 w-full rounded-xl text-sm" variant="accent" size="lg" disabled={mfaSubmitting || mfaCode.length !== 6}>
          {mfaSubmitting ? <LoaderCircle className="animate-spin" /> : <>Verify and continue <ArrowRight className="size-4" /></>}
        </Button>
        <button type="button" className="w-full text-center text-sm font-semibold text-primary hover:underline" onClick={() => { setMfaChallenge(null); setMfaCode(""); setServerError(""); }}>
          Return to sign in
        </button>
      </form>
    );
  }
  return (
    <form name={`${credentialPrefix}-form`} autoComplete="off" onSubmit={handleSubmit(onSubmit)} className="auth-form space-y-5" noValidate>
      <div><Label htmlFor={emailInputId} className="auth-field-label">Email address</Label><div className="auth-field-wrap mt-2"><Mail className="auth-field-icon" aria-hidden="true" /><Controller name="email" control={control} render={({ field }) => <Input {...field} id={emailInputId} name={`${credentialPrefix}-email`} className="auth-input min-h-12 rounded-xl bg-background/70 px-4 pl-11" type="email" autoComplete="off" placeholder="you@institution.edu" aria-invalid={Boolean(errors.email)} aria-describedby={errors.email ? "login-email-error" : undefined} />}/></div>{message(errors.email?.message, "login-email-error")}</div>
      <div><div className="flex items-center justify-between"><Label htmlFor={passwordInputId} className="auth-field-label">Password</Label><Link href={`/auth/forgot-password?portal=${portal}`} className="auth-forgot-link text-xs font-semibold">Forgot password?</Link></div><div className="auth-field-wrap mt-2"><EyeOff className="auth-field-icon" aria-hidden="true" /><Controller name="password" control={control} render={({ field }) => <Input {...field} id={passwordInputId} name={`${credentialPrefix}-password`} type={show ? "text" : "password"} autoComplete="off" className="auth-input min-h-12 rounded-xl bg-background/70 px-4 pr-12 pl-11" aria-invalid={Boolean(errors.password)} aria-describedby={errors.password ? "login-password-error" : undefined} />}/><button type="button" onClick={() => setShow(!show)} className="auth-password-toggle absolute top-1/2 right-2.5 grid size-9 -translate-y-1/2 place-items-center rounded-lg text-muted-foreground transition" aria-label={show ? "Hide password" : "Show password"}>{show ? <EyeOff className="size-4" /> : <Eye className="size-4" />}</button></div>{message(errors.password?.message, "login-password-error")}</div>
      <Controller name="remember" control={control} render={({ field }) => <div className="flex min-h-10 items-center gap-2"><Checkbox id="remember" checked={field.value} onCheckedChange={field.onChange} /><Label htmlFor="remember" className="auth-remember-label font-normal">Keep me signed in</Label></div>} />
      {serverError && <p role="alert" aria-live="assertive" className="rounded-xl border border-destructive/20 bg-destructive/10 p-3 text-sm text-destructive">{serverError}</p>}
      <Button className="auth-submit-button h-12 w-full rounded-xl text-sm" variant="accent" size="lg" disabled={isSubmitting}>{isSubmitting ? <LoaderCircle className="animate-spin" /> : <>Sign in <ArrowRight className="size-4" /></>}</Button>
      <p className="auth-register-copy text-center text-sm">New to CITIS? <Link href={`/auth/register?portal=${portal}`} className="font-semibold">Create new account</Link></p>
    </form>
  );
}

const emailSchema = z.object({ email: z.string().email("Enter a valid email address") });
const passwordSchema = z.string()
  .min(8, "Use at least 8 characters")
  .max(128, "Use 128 characters or fewer")
  .regex(/[a-z]/, "Include a lowercase letter")
  .regex(/[A-Z]/, "Include an uppercase letter")
  .regex(/\d/, "Include a number");
const resetSchema = z.object({ password: passwordSchema, confirmPassword: z.string() }).refine((data) => data.password === data.confirmPassword, { path: ["confirmPassword"], message: "Passwords do not match" });
const registerSchema = z.object({
  firstName: z.string().trim().min(1, "Enter your first name").max(80),
  lastName: z.string().trim().max(80),
  email: z.string().trim().email("Enter a valid email address"),
  password: passwordSchema,
  confirmPassword: z.string(),
}).refine((data) => data.password === data.confirmPassword, { path: ["confirmPassword"], message: "Passwords do not match" });

const registrationRoleByPortal: Record<LmsPortal, "learner" | "instructor" | "admin"> = {
  learner: "learner",
  instructor: "instructor",
  admin: "admin",
};

export function RegisterForm({ portal = "learner" }: { portal?: LmsPortal }) {
  const [done, setDone] = useState(false);
  const [serverError, setServerError] = useState("");
  const [verificationUrl, setVerificationUrl] = useState("");
  const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<z.infer<typeof registerSchema>>({
    resolver: zodResolver(registerSchema),
    defaultValues: { firstName: "", lastName: "", email: "", password: "", confirmPassword: "" },
  });
  const onSubmit = async (values: z.infer<typeof registerSchema>) => {
    setServerError("");
    try {
      const response = await apiFetch<{ data: { developmentVerificationToken?: string } }>("/auth/register", {
        method: "POST",
        body: JSON.stringify({
          firstName: values.firstName,
          lastName: values.lastName,
          email: values.email,
          password: values.password,
          role: registrationRoleByPortal[portal],
        }),
        revalidate: false,
      });
      const token = response.data.developmentVerificationToken;
      if (token) setVerificationUrl(`/auth/verify-email?token=${encodeURIComponent(token)}`);
      setDone(true);
    } catch (error) {
      setServerError(error instanceof Error ? error.message : "We could not create your account. Please try again.");
    }
  };
  if (done) {
    const staff = portal !== "learner";
    return (
      <div role="status" aria-live="polite" className="surface rounded-xl p-7 text-center">
        <CheckCircle2 className="mx-auto size-12 text-success" />
        <h3 className="mt-4 font-heading text-2xl font-semibold">Account request received</h3>
        <p className="mt-3 text-sm leading-6 text-muted-foreground">
          Verify your email to activate your account{staff ? ". An institution administrator will review staff access before you can sign in." : "."}
        </p>
        {verificationUrl && <Link href={verificationUrl} className="mt-5 inline-flex font-semibold text-primary hover:underline">Open verification link (development)</Link>}
      </div>
    );
  }
  return (
    <form onSubmit={handleSubmit(onSubmit)} className="auth-form space-y-5" noValidate>
      <div className="grid gap-5 sm:grid-cols-2">
       <div><Label htmlFor="register-first-name">First name</Label><Input id="register-first-name" className="mt-2 min-h-12 rounded-xl bg-background/70 px-4" autoComplete="given-name" aria-invalid={Boolean(errors.firstName)} aria-describedby={errors.firstName ? "register-first-name-error" : undefined} {...register("firstName")} />{message(errors.firstName?.message, "register-first-name-error")}</div>
       <div><Label htmlFor="register-last-name">Last name</Label><Input id="register-last-name" className="mt-2 min-h-12 rounded-xl bg-background/70 px-4" autoComplete="family-name" aria-invalid={Boolean(errors.lastName)} aria-describedby={errors.lastName ? "register-last-name-error" : undefined} {...register("lastName")} />{message(errors.lastName?.message, "register-last-name-error")}</div>
      </div>
      <div><Label htmlFor="register-email">Email</Label><Input id="register-email" className="mt-2 min-h-12 rounded-xl bg-background/70 px-4" type="email" autoComplete="email" placeholder="you@institution.edu" aria-invalid={Boolean(errors.email)} aria-describedby={errors.email ? "register-email-error" : undefined} {...register("email")} />{message(errors.email?.message, "register-email-error")}</div>
      <div><Label htmlFor="register-password">Password</Label><Input id="register-password" className="mt-2 min-h-12 rounded-xl bg-background/70 px-4" type="password" autoComplete="new-password" aria-invalid={Boolean(errors.password)} aria-describedby={errors.password ? "register-password-error register-password-help" : "register-password-help"} {...register("password")} />{message(errors.password?.message, "register-password-error")}<p id="register-password-help" className="mt-1 text-xs text-muted-foreground">Use 8–128 characters with upper, lower, and a number.</p></div>
      <div><Label htmlFor="register-confirm-password">Confirm password</Label><Input id="register-confirm-password" className="mt-2 min-h-12 rounded-xl bg-background/70 px-4" type="password" autoComplete="new-password" aria-invalid={Boolean(errors.confirmPassword)} aria-describedby={errors.confirmPassword ? "register-confirm-password-error" : undefined} {...register("confirmPassword")} />{message(errors.confirmPassword?.message, "register-confirm-password-error")}</div>
      {portal !== "learner" && <p className="rounded-xl border border-primary/15 bg-primary/5 p-3 text-sm text-muted-foreground">Staff accounts require email verification and institution approval before portal access is enabled.</p>}
      {serverError && <p role="alert" aria-live="assertive" className="rounded-xl border border-destructive/20 bg-destructive/10 p-3 text-sm text-destructive">{serverError}</p>}
      <Button className="h-12 w-full rounded-xl text-sm shadow-[0_12px_25px_rgba(239,125,60,.2)]" variant="accent" size="lg" disabled={isSubmitting}>{isSubmitting ? <LoaderCircle className="animate-spin" /> : "Create new account"}</Button>
    </form>
  );
}

export function ForgotPasswordForm() {
  const [done, setDone] = useState(false);
  const [serverError, setServerError] = useState("");
  const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<z.infer<typeof emailSchema>>({ resolver: zodResolver(emailSchema) });
  const onSubmit = async (values: z.infer<typeof emailSchema>) => {
    setServerError("");
    try {
      await apiFetch("/auth/forgot-password", { method: "POST", body: JSON.stringify(values), revalidate: false });
      setDone(true);
    } catch (error) {
      setServerError(error instanceof Error ? error.message : "We could not send a reset link. Please try again.");
    }
  };
  if (done) return <FormSuccess title="Check your inbox" copy="If an account exists for that email, we sent a secure password reset link." />;
  return <form onSubmit={handleSubmit(onSubmit)} className="space-y-5"><div><Label htmlFor="forgot-email">Account email</Label><Input id="forgot-email" className="mt-2" type="email" autoComplete="email" aria-invalid={Boolean(errors.email)} aria-describedby={errors.email ? "forgot-email-error" : undefined} {...register("email")} />{message(errors.email?.message, "forgot-email-error")}</div>{serverError && <p role="alert" aria-live="assertive" className="rounded-xl border border-destructive/20 bg-destructive/10 p-3 text-sm text-destructive">{serverError}</p>}<Button className="w-full" variant="accent" size="lg" disabled={isSubmitting}>{isSubmitting ? <LoaderCircle className="animate-spin" /> : "Send reset link"}</Button></form>;
}

export function ResetPasswordForm() {
  const [done, setDone] = useState(false);
  const [serverError, setServerError] = useState("");
  const [token, setToken] = useState("");
  const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<z.infer<typeof resetSchema>>({ resolver: zodResolver(resetSchema) });

  useEffect(() => {
    setToken(new URLSearchParams(window.location.search).get("token") || "");
  }, []);

  const onSubmit = async (values: z.infer<typeof resetSchema>) => {
    setServerError("");
    if (!token) {
      setServerError("Reset token is missing. Open the link from your email again.");
      return;
    }
    try {
      await apiFetch(`/auth/reset-password/${encodeURIComponent(token)}`, {
        method: "POST",
        body: JSON.stringify({ password: values.password }),
        revalidate: false,
      });
      setDone(true);
    } catch (error) {
      setServerError(error instanceof Error ? error.message : "Could not reset password.");
    }
  };
  if (done) return <FormSuccess title="Password updated" copy="Your password has been reset. You can now sign in with your new credentials." />;
  return (
    <form onSubmit={handleSubmit(onSubmit)} className="space-y-5">
      <div>
        <Label htmlFor="new-password">New password</Label>
        <Input id="new-password" className="mt-2" type="password" autoComplete="new-password" aria-invalid={Boolean(errors.password)} aria-describedby={errors.password ? "new-password-error" : "new-password-help"} {...register("password")} />
        {message(errors.password?.message, "new-password-error")}
        <p id="new-password-help" className="mt-1 text-xs text-muted-foreground">Use at least 8 characters with upper, lower, and a number.</p>
      </div>
      <div>
        <Label htmlFor="confirm-password">Confirm password</Label>
        <Input id="confirm-password" className="mt-2" type="password" autoComplete="new-password" aria-invalid={Boolean(errors.confirmPassword)} aria-describedby={errors.confirmPassword ? "confirm-password-error" : undefined} {...register("confirmPassword")} />
        {message(errors.confirmPassword?.message, "confirm-password-error")}
      </div>
      {serverError ? <p role="alert" aria-live="assertive" className="text-sm text-red-600">{serverError}</p> : null}
      <Button className="w-full" variant="accent" size="lg" disabled={isSubmitting}>
        {isSubmitting ? <LoaderCircle className="animate-spin" /> : "Set new password"}
      </Button>
    </form>
  );
}
